    {
      "slug": "default",
      "name": "Standard A4 Landscape Grid",
      "description": "Full-width grid layout for landscape orientation. Shows all class schedules sorted by dates and time slots.",
      "source": "{{!--\n  Exam Time Table Template — A4 landscape.\n  Context: school, session, exam, columns (array), rows (array).\n--}}\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<style>\n    @page { size: A4 landscape; margin: 10mm; }\n    * { box-sizing: border-box; }\n    body { font-family: Arial, Helvetica, sans-serif; color: #1a1a1a; margin: 0; padding: 0; background: #fff; }\n    \n    .head { display: flex; align-items: center; gap: 14px; border-bottom: 3px solid #1a1a1a; padding-bottom: 10px; margin-bottom: 14px; }\n    .head img { height: 56px; width: 56px; object-fit: contain; }\n    .head .title { flex: 1; }\n    .head h1 { margin: 0; font-size: 20px; font-weight: 700; letter-spacing: -0.5px; }\n    .head .sub { color: #555; font-size: 12px; margin-top: 2px; }\n    .head .exam { text-align: right; }\n    .head .exam .name { font-size: 16px; font-weight: bold; }\n    .head .exam .yr { font-size: 11px; color: #555; margin-top: 1px; }\n\n    table { width: 100%; border-collapse: collapse; font-size: 11px; margin-top: 10px; }\n    th, td { border: 1px solid #999; padding: 8px 10px; text-align: center; vertical-align: middle; }\n    thead th { background: #f5f5f5; font-weight: 700; font-size: 11px; }\n    th.cls { min-width: 90px; }\n    \n    td.date .d { font-weight: bold; }\n    td.date .dow { font-size: 10px; color: #666; margin-top: 1px; }\n    td.time { white-space: nowrap; color: #333; font-size: 10px; line-height: 1.3; }\n    td.slot { font-size: 11px; font-weight: 500; }\n    td.slot .empty { color: #ccc; font-weight: normal; }\n    td.slot .sub-cell { margin: 2px 0; }\n    td.slot .sub-cell:not(:last-child) { border-bottom: 1px dashed #eee; padding-bottom: 2px; }\n    \n    thead th.date, thead th.time { background: #eaeaea; }\n    .foot { margin-top: 16px; font-size: 10px; color: #666; text-align: right; font-style: italic; }\n</style>\n</head>\n<body>\n    <div class=\"head\">\n        {{#if school.logoUrl}}\n            <img src=\"{{school.logoUrl}}\" alt=\"logo\">\n        {{/if}}\n        <div class=\"title\">\n            <h1>{{school.name}}</h1>\n            <div class=\"sub\">{{school.location}}</div>\n        </div>\n        <div class=\"exam\">\n            <div class=\"name\">{{exam.name}} — Time Table</div>\n            <div class=\"yr\">Session {{session.startYear}}–{{session.endYear}}</div>\n        </div>\n    </div>\n    \n    <table>\n        <thead>\n            <tr>\n                <th class=\"date\">Date</th>\n                <th class=\"time\">Time</th>\n                {{#each columns}}\n                    <th class=\"cls\">{{this.label}}</th>\n                {{/each}}\n            </tr>\n        </thead>\n        <tbody>\n            {{#each rows}}\n                <tr>\n                    <td class=\"date\">\n                        <div class=\"d\">{{this.displayDate}}</div>\n                        <div class=\"dow\">{{this.dayOfWeek}}</div>\n                    </td>\n                    <td class=\"time\">{{this.startTime}}<br>–<br>{{this.endTime}}</td>\n                    {{#each ../columns}}\n                        <td class=\"slot\">\n                            {{#with (lookup ../cells this.classId) as |cellVal|}}\n                                {{#if cellVal.subjectName}}\n                                    {{cellVal.subjectName}} — {{cellVal.modeName}}\n                                {{else}}\n                                    {{#each cellVal}}\n                                        <div class=\"sub-cell\">\n                                            {{this.subjectName}} — {{this.modeName}}\n                                        </div>\n                                    {{/each}}\n                                {{/if}}\n                            {{else}}\n                                <span class=\"empty\">—</span>\n                            {{/with}}\n                        </td>\n                    {{/each}}\n                </tr>\n            {{else}}\n                <tr>\n                    <td colspan=\"{{add columns.length 2}}\">No exams scheduled.</td>\n                </tr>\n            {{/each}}\n        </tbody>\n    </table>\n    \n    <div class=\"foot\">Each cell shows the subject and examination mode for the respective class in that time slot.</div>\n</body>\n</html>\n"
    },
    {
      "slug": "centered",
      "name": "Centered Grid with Fee Clearance Note",
      "description": "Centered A4 landscape grid layout. Features dual logos, optional school registration number, and a fee clearance reminder at the bottom.",
      "source": "{{!--\n  Exam Time Table Centered Template — A4 landscape.\n  Context: school, session, exam, columns (array), rows (array).\n--}}\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<style>\n    @page { size: A4 landscape; margin: 10mm; }\n    * { box-sizing: border-box; }\n    body { font-family: Arial, Helvetica, sans-serif; color: #1a1a1a; margin: 0; padding: 0; background: #fff; text-align: center; }\n    \n    .head { display: flex; align-items: center; justify-content: space-between; border-bottom: 3px solid #1a1a1a; padding-bottom: 10px; margin-bottom: 14px; }\n    .head img { height: 60px; width: 60px; object-fit: contain; }\n    .head .title-container { flex: 1; text-align: center; padding: 0 15px; }\n    .head h1 { margin: 0; font-size: 22px; font-weight: 700; letter-spacing: -0.5px; text-transform: uppercase; }\n    .head .sub { color: #444; font-size: 13px; margin-top: 3px; font-weight: 500; }\n    .head .reg-no { font-size: 11px; color: #666; margin-top: 2px; font-style: italic; }\n    \n    .exam-info { margin: 10px 0 15px 0; text-align: center; }\n    .exam-info .name { font-size: 18px; font-weight: bold; text-transform: uppercase; color: #111; }\n    .exam-info .yr { font-size: 12px; color: #555; margin-top: 2px; font-weight: 600; }\n\n    table { width: 100%; border-collapse: collapse; font-size: 11px; margin: 0 auto; }\n    th, td { border: 1px solid #777; padding: 8px 10px; text-align: center; vertical-align: middle; }\n    thead th { background: #f0f0f0; font-weight: 700; font-size: 11px; text-transform: uppercase; }\n    th.cls { min-width: 90px; }\n    \n    td.date .d { font-weight: bold; }\n    td.date .dow { font-size: 10px; color: #555; margin-top: 1px; }\n    td.time { white-space: nowrap; color: #222; font-size: 10px; line-height: 1.3; font-weight: 600; }\n    td.slot { font-size: 11px; font-weight: 600; }\n    td.slot .empty { color: #bbb; font-weight: normal; }\n    td.slot .sub-cell { margin: 3px 0; padding: 2px 0; }\n    td.slot .sub-cell:not(:last-child) { border-bottom: 1px dashed #ddd; }\n    \n    thead th.date, thead th.time { background: #e5e5e5; }\n    \n    .note-container { margin-top: 20px; padding: 10px; border: 1px solid #ccc; background-color: #fafafa; border-radius: 4px; display: inline-block; }\n    .fee-note { font-size: 12px; color: #c00; font-weight: bold; text-align: center; }\n    .foot { margin-top: 10px; font-size: 9px; color: #666; text-align: center; font-style: italic; }\n</style>\n</head>\n<body>\n    <div class=\"head\">\n        {{#if school.logoUrl}}\n            <img src=\"{{school.logoUrl}}\" alt=\"logo\">\n        {{else}}\n            <div style=\"width: 60px;\"></div>\n        {{/if}}\n        \n        <div class=\"title-container\">\n            <h1>{{school.name}}</h1>\n            <div class=\"sub\">{{school.location}}</div>\n            {{#if school.registrationNo}}\n                <div class=\"reg-no\">Registration No: {{school.registrationNo}}</div>\n            {{/if}}\n        </div>\n\n        {{#if school.logoUrl}}\n            <img src=\"{{school.logoUrl}}\" alt=\"logo\">\n        {{else}}\n            <div style=\"width: 60px;\"></div>\n        {{/if}}\n    </div>\n    \n    <div class=\"exam-info\">\n        <div class=\"name\">{{exam.name}} — Time Table</div>\n        <div class=\"yr\">Session {{session.startYear}}–{{session.endYear}}</div>\n    </div>\n    \n    <table>\n        <thead>\n            <tr>\n                <th class=\"date\">Date</th>\n                <th class=\"time\">Time</th>\n                {{#each columns}}\n                    <th class=\"cls\">{{this.label}}</th>\n                {{/each}}\n            </tr>\n        </thead>\n        <tbody>\n            {{#each rows}}\n                <tr>\n                    <td class=\"date\">\n                        <div class=\"d\">{{this.displayDate}}</div>\n                        <div class=\"dow\">{{this.dayOfWeek}}</div>\n                    </td>\n                    <td class=\"time\">{{this.startTime}}<br>–<br>{{this.endTime}}</td>\n                    {{#each ../columns}}\n                        <td class=\"slot\">\n                            {{#with (lookup ../cells this.classId) as |cellVal|}}\n                                {{#if cellVal.subjectName}}\n                                    {{cellVal.subjectName}} — {{cellVal.modeName}}\n                                {{else}}\n                                    {{#each cellVal}}\n                                        <div class=\"sub-cell\">\n                                            {{this.subjectName}} — {{this.modeName}}\n                                        </div>\n                                    {{/each}}\n                                {{/if}}\n                            {{else}}\n                                <span class=\"empty\">—</span>\n                            {{/with}}\n                        </td>\n                    {{/each}}\n                </tr>\n            {{else}}\n                <tr>\n                    <td colspan=\"{{add columns.length 2}}\">No exams scheduled.</td>\n                </tr>\n            {{/each}}\n        </tbody>\n    </table>\n    \n    <div class=\"note-container\">\n        <div class=\"fee-note\">Kindly clear your school Fee upto the day of examination(Including exam fee)</div>\n    </div>\n    \n    <div class=\"foot\">Each cell shows the subject and examination mode for the respective class in that time slot.</div>\n</body>\n</html>\n"
    }
